theme.css:
/* theme: Meltdown Morning | A historic AI rout bleeds through the page in reds and shattered white, with panic lines cutting every card like falling tickers. */
/* mood: bad */
/* layout: hero=centered; political-news=timeline/stack; financial-news=stat/stack; entertainment-news=tile/masonry; sports=numbered/grid-2; music-releases=plain/stack; stock-analysis=banner/grid-3; outlook=outline/stack */

.diary-page {
  --paper: #1c0b0d;
  --paper-alt: #2a1013;
  --ink: #f5e9ea;
  --ink-soft: #d9c2c6;
  --muted: #a98f93;
  --accent: #ff5c5c;
  --accent-ink: #1c0b0d;
  --rule: #4a2529;
  --font-display: var(--ff-playfair), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;
}

@media (prefers-color-scheme: dark) {
  .diary-page {
    --paper: #1c0b0d;
    --paper-alt: #2a1013;
    --ink: #f5e9ea;
    --ink-soft: #d9c2c6;
    --muted: #a98f93;
    --accent: #ff5c5c;
    --accent-ink: #1c0b0d;
    --rule: #4a2529;
  }
}

/* Torched skyline header: centered, bleeding red blotches */
.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 2px solid var(--accent);
  position: relative;
  overflow: hidden;
}

.diary-page .diary-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 20% 120%, var(--accent) 0%, transparent 55%), radial-gradient(ellipse at 80% -50%, var(--accent) 0%, transparent 60%);
  opacity: 0.15;
  pointer-events: none;
}

.diary-page[data-hero="centered"] .diary-hero-inner {
  text-align: center;
  padding-block: 2rem 3.5rem;
  position: relative;
}

.diary-page[data-hero="centered"] .diary-title,
.diary-page[data-hero="centered"] .diary-summary,
.diary-page[data-hero="centered"] .diary-theme-note {
  margin-inline: auto;
}

.diary-page[data-hero="centered"] .diary-crumbs {
  display: block;
  margin-bottom: 1.5rem;
}

.diary-page .diary-kicker {
  color: var(--accent);
  letter-spacing: 0.22em;
  font-weight: 700;
  text-transform: uppercase;
  margin-top: 1.75rem;
  font-size: 0.82rem;
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(2.5rem, 6.5vw, 5.5rem);
  letter-spacing: -0.02em;
  line-height: 1.05;
  max-width: 24ch;
  color: var(--ink);
  text-shadow: 0 2px 12px rgb(0 0 0 / 0.4), 0 0 40px rgb(255 92 92 / 0.15);
}

.diary-page .diary-summary {
  color: var(--ink-soft);
  font-size: clamp(1.1rem, 1.8vw, 1.35rem);
  max-width: 40rem;
  margin-top: 1.25rem;
  border-top: 1px solid var(--rule);
  padding-top: 1.25rem;
}

.diary-page .diary-theme-note {
  margin-top: 1.5rem;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 0;
  padding: 0.2rem 0.8rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.78rem;
}

/* Contents: stricken ticker marks */
.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  font-family: var(--font-ui);
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-bottom:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
  font-weight: 700;
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }
}

/* Rain of blood and oil: section heads */
.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  position: relative;
}

.diary-page .diary-section::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, var(--accent) 0%, var(--rule) 25%, transparent 50%, var(--rule) 75%, var(--accent) 100%);
  opacity: 0.5;
}

.diary-page .diary-section-number {
  color: var(--accent);
  font-weight: 700;
  letter-spacing: 0.14em;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--ink);
}

/* body text */
.diary-page .diary-prose {
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom-color: var(--accent);
  font-family: var(--font-ui);
  font-weight: 600;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose code,
.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-prose hr {
  border-top-color: var(--rule);
}

/* Drop cap: shrieking red */
.diary-page .diary-section:first-child .diary-card--plain:first-child .diary-prose > p:first-of-type::first-letter {
  font-family: var(--font-display);
  color: var(--accent);
  font-size: 4.2em;
}

/* Cards: sharp corners, brittle edges */
.diary-page .diary-card {
  container-type: inline-size;
}

.diary-page .diary-card-inner {
  gap: 0.6rem;
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.15;
  color: var(--ink);
}

.diary-page .diary-card-body {
  color: var(--ink-soft);
}

/* Political News — timeline of a cascade */
.diary-page [data-section="political-news"] .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
}

.diary-page [data-section="political-news"] .diary-card--timeline .diary-card-inner::before {
  background: var(--rule);
  width: 1px;
}

.diary-page [data-section="political-news"] .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  width: 1rem;
  height: 1rem;
  top: 0.4rem;
  left: -0.15rem;
  box-shadow: 0 0 0 0 var(--paper), 0 0 12px 2px rgb(255 92 92 / 0.4);
  border-radius: 0;
  transform: rotate(45deg);
}

.diary-page [data-section="political-news"] .diary-card-title {
  font-size: 1.75rem;
}

/* Financial News — the headline loss, huge */
.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-inner {
  border-top: 3px solid var(--accent);
}

.diary-page [data-section="financial-news"] .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(3rem, 16cqi, 5.5rem);
  font-weight: 700;
  color: var(--accent);
  letter-spacing: -0.03em;
  line-height: 0.95;
  margin-bottom: 0.5rem;
}

.diary-page [data-section="financial-news"] .diary-card-title {
  font-size: 2rem;
}

.diary-page [data-section="financial-news"] .diary-prose {
  font-size: 1.2rem;
}

/* Entertainment — broken glass mosaic */
.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-inner {
  padding: 1.25rem 1.5rem;
  transition: border-color 180ms, transform 180ms;
}

.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
  box-shadow: 0 6px 18px -8px rgb(0 0 0 / 0.6);
}

.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-inner:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}

.diary-page [data-section="entertainment-news"] .diary-card-title {
  font-size: 1.25rem;
}

.diary-page [data-section="entertainment-news"] .diary-card-thread {
  border-color: var(--accent);
  background: transparent;
  color: var(--accent);
}

.diary-page [data-section="entertainment-news"] .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Sports — falling numerals */
.diary-page [data-section="sports"] .diary-card--numbered .diary-card-inner {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.5rem 1.25rem;
}

.diary-page [data-section="sports"] .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-size: 3.5rem;
  font-weight: 700;
  color: var(--accent);
  opacity: 0.8;
  line-height: 0.9;
  grid-row: 1 / span 3;
}

.diary-page [data-section="sports"] .diary-card--numbered .diary-card-inner > :not(.diary-card-index) {
  grid-column: 2;
}

.diary-page [data-section="sports"] .diary-card-title {
  font-size: 1.5rem;
}

/* Stock Analysis — panic banners */
.diary-page [data-section="stock-analysis"] .diary-card--banner .diary-card-inner {
  gap: 0;
  overflow: hidden;
  border: 1px solid var(--rule);
  border-radius: 0;
  background: var(--paper-alt);
}

.diary-page [data-section="stock-analysis"] .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 1.05rem;
  font-weight: 700;
  padding: 0.65rem 1.1rem;
  border-radius: 0;
}

.diary-page [data-section="stock-analysis"] .diary-card--banner .diary-card-body {
  padding: 0.9rem 1.1rem 1.1rem;
  font-size: 1rem;
}

.diary-page [data-section="stock-analysis"] .diary-card--banner .diary-card-thread {
  margin: 0 1.1rem 0;
  border-color: var(--accent);
}

.diary-page [data-section="stock-analysis"] .diary-card--banner .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Outlook — black ledger */
.diary-page [data-section="outlook"] .diary-card--outline .diary-card-inner {
  padding: 1.25rem 1.5rem;
  border: 1px solid var(--rule);
  border-radius: 0;
  border-left: 3px solid var(--accent);
}

.diary-page [data-section="outlook"] .diary-card-title {
  font-size: 1.4rem;
}

/* Music — players stand bare on the burning floor */
.diary-page [data-section="music-releases"] .diary-card--plain {
  border-bottom: 1px solid var(--rule);
  padding-bottom: 1.25rem;
}

.diary-page [data-section="music-releases"] .diary-card:last-child {
  border-bottom: 0;
}

.diary-page [data-section="music-releases"] .diary-card-title {
  font-size: 1.5rem;
}

.diary-page [data-section="music-releases"] .diary-prose {
  font-size: 1.05rem;
}

/* Sparks: red and black ticker */
.diary-page .diary-markets-wrap {
  margin-bottom: 2.5rem;
}

.diary-page .diary-markets-label {
  color: var(--muted);
  font-family: var(--font-ui);
  letter-spacing: 0.16em;
}

.diary-page .diary-markets {
  grid-template-columns: repeat(auto-fill, minmax(10rem, 1fr));
  gap: 0.5rem;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
  position: relative;
  overflow: hidden;
}

.diary-page .diary-spark::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 2px;
  height: 100%;
  background: var(--accent);
  opacity: 0.5;
}

.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark-line polyline {
  stroke-width: 2;
  fill: none;
}

.diary-page .diary-spark.is-up .diary-spark-line polyline {
  stroke: var(--ink);
}

.diary-page .diary-spark.is-down .diary-spark-line polyline {
  stroke: var(--accent);
}

/* Footer: singed edges */
.diary-page .diary-footer {
  border-top-color: var(--rule);
  color: var(--muted);
  font-family: var(--font-ui);
}

.diary-page .diary-footer a {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Subtle entropy: cards shift once on load, nothing loops */
@media (prefers-reduced-motion: no-preference) {
  .diary-page .diary-section {
    animation: diary-fall-through 800ms ease-out both;
  }

  .diary-page .diary-section:nth-of-type(2n) {
    animation-delay: 60ms;
  }

  .diary-page .diary-section:nth-of-type(3n) {
    animation-delay: 120ms;
  }
}

@keyframes diary-fall-through {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Cards breathe once, barely */
@media (prefers-reduced-motion: no-preference) {
  .diary-page .diary-stories--grid-2 .diary-card,
  .diary-page .diary-stories--grid-3 .diary-card,
  .diary-page .diary-stories--feature .diary-card {
    transition: border-color 240ms ease, box-shadow 240ms ease;
  }

  .diary-page .diary-stories--grid-2 .diary-card:hover,
  .diary-page .diary-stories--grid-3 .diary-card:hover,
  .diary-page .diary-stories--feature .diary-card:hover {
    border-color: transparent;
  }
}

/* Keep the long publisher names from breaking the grid */
.diary-page .diary-prose a {
  overflow-wrap: anywhere !important;
}

/* Make sure the hero is legible on the alt paper */
.diary-page .diary-hero-inner .diary-crumbs a,
.diary-page .diary-hero-inner .diary-kicker,
.diary-page .diary-hero-inner .diary-title,
.diary-page .diary-hero-inner .diary-summary,
.diary-page .diary-hero-inner .diary-theme-note {
  text-shadow: 0 1px 8px rgb(0 0 0 / 0.35);
}
